 * 超时升级：PENDING_CONFIRM→ESCALATED，同时冻结排放总量基数（同事务），返回 0 表示无需升级。
 * 条件 confirm_deadline &lt;= now 保证“恰满 2 小时”当刻即升级，早一刻不升级。
 */
public int escalateOrder(String orderNo, LocalDateTime now) {
    return jdbc.update("UPDATE restriction_order SET status = 'ESCALATED', escalated_at = ?, "
                    + "escalate_reason = '确认执行期限届满（下达后恰满2小时未确认），自动升级并联动限产', "
                    + "frozen_total_qty = COALESCE(frozen_total_qty, 0), active_slot = outlet_code, "
                    + "updated_at = ? WHERE order_no = ? AND status = 'PENDING_CONFIRM' AND confirm_deadline <= ?",
            Timestamp.valueOf(now), Timestamp.valueOf(now), orderNo, Timestamp.valueOf(now));
}

