/**
 * 幂等执行：指纹覆盖 requestId 与全部业务字段。
 * 同键同参返回首次结果；同键异参抛 409 且不执行动作、不改变排口状态。
 */
private <T> T replayable(String requestId, String requestType, Map<String, Object> fields,
                         Class<T> resultType, Supplier<T> action) {
    String rid = requireText(requestId, "requestId");
    String fingerprint = idem.fingerprint(rid, fields);
    Map<String, Object> existing = repo.findIdempotent(rid);
    if (existing != null) {
        if (!fingerprint.equals(existing.get("fingerprint"))) {
            throw new ConflictException("requestId=" + rid + " 请求参数与首次调用不一致（409 幂等冲突）");
        }
        return idem.fromJson((String) existing.get("result_json"), resultType);
    }
    T result = action.get();
    if (!repo.insertIdempotent(rid, requestType, fingerprint, idem.toJson(result), clock.now())) {
        Map<String, Object> raced = repo.findIdempotent(rid);
        if (raced == null || !fingerprint.equals(raced.get("fingerprint"))) {
            throw new ConflictException("requestId=" + rid + " 并发请求参数冲突");
        }
        return idem.fromJson((String) raced.get("result_json"), resultType);
    }
    return result;
}

